  record: Record,
  keys: List[String]
)(using vr: org.goldenport.convert.ValueReader[A]): Consequence[Option[Vector[A]]] = {
  def decode_all(xs: Seq[?]): Consequence[Vector[A]] =
    xs.foldLeft(Consequence.success(Vector.empty[A])) { (z, x) =>
      z.flatMap(zs => vr.readC(x).map(a => zs :+ a))
    }
