          case Some(xs: Seq[?]) => decode_all(xs).map(Some(_))
          case Some(xs: Array[?]) => decode_all(xs.toVector).map(Some(_))
          case Some(other) => vr.readC(other).map(x => Some(Vector(x)))
          case None => Consequence.success(None)
        }
    }
  }
}

